function validate([grid]) {
  const n = grid.length;
  if (n < 2 || n > 50) return 'grid needs 2 to 50 rows.';
  if (grid.some(row => row.length !== n)) return 'grid must be square (n rows of n numbers).';
  const total = n * n;
  const count = new Array(total + 1).fill(0);
  for (const row of grid) for (const v of row) {
    if (!Number.isInteger(v) || v < 1 || v > total) return 'Each entry is between 1 and n * n.';
    count[v]++;
  }
  let twice = 0, absent = 0;
  for (let x = 1; x <= total; x++) {
    if (count[x] === 0) absent++;
    else if (count[x] === 2) twice++;
    else if (count[x] !== 1) return 'Only one number may appear twice; no number appears three or more times.';
  }
  if (twice !== 1 || absent !== 1) return 'Exactly one number must appear twice and exactly one must be absent.';
  return null;
}

