function findMissingAndRepeatedValues(grid) {
  const n = grid.length;
  const total = n * n;
  const count = new Array(total + 1).fill(0);

  for (const row of grid) {
    for (const value of row) {
      count[value]++;
    }
  }

  let repeated = 0;
  let missing = 0;
  for (let value = 1; value <= total; value++) {
    if (count[value] === 2) {
      repeated = value;
    } else if (count[value] === 0) {
      missing = value;
    }
  }
  return [repeated, missing];
}

