function findMissingAndRepeatedValues(grid) {
  const flat = grid.flat();
  const answer = [0, 0];
  for (let x = 1; x <= flat.length; x++) {
    const times = flat.filter(v => v === x).length;
    if (times === 2) answer[0] = x;
    if (times === 0) answer[1] = x;
  }
  return answer;
}

