function generate(rand, size) {
  const n = size === 'large' ? 40 + Math.floor(rand() * 11) : 2 + Math.floor(rand() * 4);
  const total = n * n;
  const values = Array.from({ length: total }, (_, i) => i + 1);
  // Choose the absent number b and a different number a to take its place.
  const pick = () => 1 + Math.floor(rand() * total);
  const roll = rand();
  const missing = roll < 0.15 ? 1 : roll < 0.3 ? total : pick();
  let repeated = pick();
  while (repeated === missing) repeated = pick();
  values[missing - 1] = repeated;
  for (let i = values.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  const grid = [];
  for (let r = 0; r < n; r++) grid.push(values.slice(r * n, (r + 1) * n));
  return [grid];
}
